import Modal from "../../002 01-starting-project/01-starting-project/src/components/UI/Modal";
import "./Cart.css";
import React,{useState} from 'react';

const Cart=({items})=>{
       const [openCart, setOpenCart]=useState(false);

       const handleCart=()=>{
        setOpenCart(true);
       }
    return(
        
        <div className="cart">
            <label>items</label>
            <span>{items.amount}</span>  
            <div className="button-div">
                <button className="cart-button" onClick={handleCart}>Open Cart</button>
            </div>
           {openCart && (
            <Modal>
            <ul>
        
        {items.map((item, index) => (
          <li key={index}>
             <span>X{item.amount}</span> 
            <span>{item.name}</span> 
           
            <span>{item.price}</span>
          </li>
        ))}
      </ul>
            </Modal>
            )} 
        </div>
       

      
    )
}
export default Cart;
